configfiles.configfile:
library(WGCNA) library(igraph) library(svglite) options(stringsAsFactors = FALSE)
## Galaxy parameters counts_file <- "$counts_file" metadata_file <- "$metadata_file" network_type <- "$network_type" tom_type <- "$tom_type" cor_type <- "$cor_type" min_module_size <- as.integer($min_module_size) merge_cut_height <- as.numeric($merge_cut_height) me_cor_threshold <- as.numeric($me_cor_threshold) plot_resolution <- as.integer($plot_resolution) image_format <- "$image_format"
log_transform <- $log_transform filter_by_variance <- $filter_by_variance variance_quantile <- as.numeric($variance_quantile) run_sample_gene_qc <- $run_sample_gene_qc
## Use GALAXY_SLOTS if set by the cluster runner, fall back to 4 otherwise n_threads <- as.integer(Sys.getenv("GALAXY_SLOTS", unset = "4")) allowWGCNAThreads(nThreads = n_threads)
## corFnc/adjacency()/TOMsimilarity() expect the *function name* ("cor" or ## "bicor"), whereas blockwiseModules()'s corType expects "pearson"/"bicor". ## Keep both derived from the single user-facing cor_type parameter so the ## correlation method is consistent across every step of the pipeline. cor_fnc <- ifelse(cor_type == "bicor", "bicor", "cor")
## Read soft power from config file if provided, else use manual value #if $softpower_config: sft_config <- readLines("$softpower_config") soft_power_line <- grep("^soft_power\\s*=", sft_config, value = TRUE)[1] if (is.na(soft_power_line) || !nzchar(soft_power_line)) { stop("Could not find a 'soft_power' entry in the provided soft-thresholding config file.") } soft_power <- suppressWarnings(as.integer(trimws(strsplit(soft_power_line, "=", fixed = TRUE)[[1]][2]))) if (is.na(soft_power)) { stop("The soft power value read from the config file is not a valid integer.") } ## Cross-checking the network_type and variance_quantile that has been recorded in the soft-thresholding ## config. A network_type mismatch is fatal as signed vs. unsigned softpowers are not comparable, hence stopping the script. ## wheras, a variance_quantile mismatching means that the power was estimated on a slightly different filtered gene set, resulting ## it to be a warning and not a hard failure. cfg_network_type_line <- grep("^network_type\\s*=", sft_config, value = TRUE)[1] if (!is.na(cfg_network_type_line) && nzchar(cfg_network_type_line)) { cfg_network_type <- trimws(strsplit(cfg_network_type_line, "=", fixed = TRUE)[[1]][2]) if (nzchar(cfg_network_type) && cfg_network_type != network_type) { stop("Network type in soft-thresholding config (", cfg_network_type, ") does not match the selected network type (", network_type, ").") } } cfg_variance_line <- grep("^variance_quantile\\s*=", sft_config, value = TRUE)[1] if (filter_by_variance && !is.na(cfg_variance_line) && nzchar(cfg_variance_line)) { cfg_variance_quantile <- suppressWarnings(as.numeric(trimws(strsplit(cfg_variance_line, "=", fixed = TRUE)[[1]][2]))) if (is.finite(cfg_variance_quantile) && !isTRUE(all.equal(cfg_variance_quantile, variance_quantile))) { warning("Variance quantile in soft-thresholding config (", cfg_variance_quantile, ") does not match the selected variance_quantile (", variance_quantile, ").") } } cfg_cor_fnc_line <- grep("^corFnc\\s*=", sft_config, value = TRUE)[1] if (!is.na(cfg_cor_fnc_line) && nzchar(cfg_cor_fnc_line)) { cfg_cor_fnc <- trimws(strsplit(cfg_cor_fnc_line, "=", fixed = TRUE)[[1]][2]) if (nzchar(cfg_cor_fnc) && cfg_cor_fnc != cor_fnc) { warning("Correlation function in soft-thresholding config (", cfg_cor_fnc, ") does not match the selected correlation function (", cor_fnc, ").") } } cat("Soft power loaded from config file:", soft_power, "\n") #else: soft_power <- as.integer("$soft_power") cat("Soft power set manually:", soft_power, "\n") #end if
## trait_columns arrives as a comma-separated string from the Galaxy ## data_column parameter (with use_header_names=true this is column names, ## e.g. "age_at_diagnosis,sample_group"; in tool tests it may be indices). trait_tokens <- trimws(strsplit("$trait_columns", ",")[[1]]) trait_tokens <- trait_tokens[nzchar(trait_tokens)] if (length(trait_tokens) == 0) { stop("No trait columns selected.") }
cat("Config loaded. Starting WGCNA analysis...\n")
## Build a numeric trait matrix from a metadata data.frame. ## Numeric columns are used as-is; non-numeric (categorical) columns are ## one-hot encoded via model.matrix(). NA values in categorical columns are ## kept as their own explicit "NA" level rather than being silently dropped ## (model.matrix() drops NA rows by default, which would otherwise cause ## samples with missing categorical traits to disappear from the matrix). prepare_trait_matrix <- function(meta, sample_col = 1) { sample_ids <- meta[[sample_col]] meta_data <- meta[, -sample_col, drop = FALSE]
## Collect one piece (a numeric vector or a one-hot matrix) per column, ## then combine them all in a single do.call(cbind, ...) rather than ## repeatedly growing the result with cbind() inside the loop. pieces <- list() for (col_name in names(meta_data)) { col_values <- meta_data[[col_name]]
if (is.numeric(col_values)) { pieces[[col_name]] <- col_values } else { col_factor <- factor(col_values) mm <- model.matrix(~ col_factor - 1) colnames(mm) <- paste0(col_name, "_", levels(col_factor)) if (any(is.na(col_values))) { mm_full <- matrix(NA_real_, nrow = length(col_values), ncol = ncol(mm), dimnames = list(NULL, colnames(mm))) complete_rows <- which(!is.na(col_values)) mm_full[complete_rows, ] <- mm pieces[[col_name]] <- mm_full } else { pieces[[col_name]] <- mm } } }
result <- as.data.frame(do.call(cbind, pieces)) rownames(result) <- as.character(sample_ids) return(result) }
## Human-readable trait names for plot axes (underscores become spaces). prettify_trait_label <- function(labels) { vapply(labels, function(label) { gsub("_", " ", label) }, character(1), USE.NAMES = FALSE) }
## ── DPI-aware margin / dimension safety helpers ────────────────────────────── ## R's par(mar = c(bottom,left,top,right)) uses *text lines*. At a given ## (width_px, height_px, dpi) the figure has a physical size in inches, and ## each text line occupies roughly 1/5 of an inch at default cex. When the ## user-facing plot_resolution is high (e.g. 300 dpi) the pixel dimensions ## that were tuned for 72 dpi produce a tiny figure in inches, and the ## per-character margin formulas often claim more lines than the figure can ## physically hold, leading to the classic 'figure margins too large' error. ## ## These helpers (a) compute a 'dpi-safe' pixel canvas that preserves the ## intended physical size in inches (so the same mar values always fit), and ## (b) provide a cap so mar values can never exceed ~70% of the figure even ## when downstream code (e.g. WGCNA::plotDendroAndColors) overrides them. ## ## NOTE: this script is rendered through Galaxy/Cheetah before Rscript ever ## sees it, and Cheetah treats any bare "$identifier" as a template variable ## to substitute. That's why every list access below (and throughout this ## script) uses R's `x[["name"]]` form instead of `x$name` -- `x$name` would ## be silently (and incorrectly) parsed by Cheetah as "$name", breaking ## config rendering for every job, not just this one.
REF_DPI <- 72 ## Slightly under the geometric 1/5in-per-line rule of thumb, to leave ## headroom now that BASE_POINTSIZE below is larger. LINES_PER_INCH_REF <- 4.5 ## Kept well under common raster-backend limits (Cairo's image surface caps ## out around 32767px per side, and huge canvases can also exhaust memory: ## a 12000x12000 RGBA bitmap is already ~580MB). 9000px is still very high ## resolution at typical DPI settings, keeps worst-case memory usage in ## check, and leaves a comfortable safety margin so png()/tiff() never ## fail even when the data-driven dimension formulas below grow large. MAX_PNG_DIM <- 9000
dpi_safe_dims <- function(width_px, height_px, ref_dpi = REF_DPI, target_dpi = plot_resolution, max_dim = MAX_PNG_DIM) { scale <- max(1, target_dpi / ref_dpi) list( width = min(max_dim, as.integer(ceiling(width_px * scale))), height = min(max_dim, as.integer(ceiling(height_px * scale))) ) }
safe_dim <- function(px, max_dim = MAX_PNG_DIM) min(max_dim, as.integer(px))
## Reference canvas (in the same base, pre-DPI-scaling px units passed to ## open_plot_device) at which BASE_POINTSIZE looks right. Plots whose base ## canvas grows with the amount of data (more samples/genes/modules/traits) ## get a proportionally larger pointsize so labels don't shrink relative to ## the figure as it grows; sqrt() dampens that growth so text doesn't ## become oversized on very large canvases. Plots with a fixed base canvas ## simply get BASE_POINTSIZE. BASE_POINTSIZE <- 18 REF_CANVAS_DIAG <- sqrt(1600^2 + 900^2)
scaled_pointsize <- function(width_px, height_px, base_pointsize = BASE_POINTSIZE, min_pointsize = 14, max_pointsize = 26) { diag_ratio <- sqrt(width_px^2 + height_px^2) / REF_CANVAS_DIAG ps <- round(base_pointsize * sqrt(diag_ratio)) max(min_pointsize, min(max_pointsize, ps)) }
## Open a plot device that keeps the intended physical size (base_px / ## REF_DPI inches), in whichever raster or vector format the user selected ## via image_format ("png", "jpg", "pdf", or "svg"). Always scale *both* ## width and height; scaling only one axis produces a squeezed canvas that ## clips titles/labels. ## ## Raster formats (png/jpg) share identical width/height/res/pointsize ## semantics, so they're opened the same way at dpi-scaled pixel dimensions. ## pdf() and svglite() are vector devices: they take width/height in ## *inches*, have no res argument, and text scales losslessly with ## pointsize regardless of dpi -- so instead of scaling pixel counts by ## plot_resolution, we convert the same base_px values straight to inches ## at REF_DPI. Either way, the returned `dims` list is always in the same ## dpi-scaled pixel-equivalent units, so cap_mar_to_figure()'s ## margin-in-lines math (which only cares about physical inches, not ## literal pixels) produces identical layouts no matter which format was ## chosen. svglite() (rather than base R's svg()) is used so SVG output ## does not depend on the R build having Cairo support. ## ## pointsize defaults to NULL, which auto-scales via scaled_pointsize() based ## on the (pre-DPI) canvas size; pass an explicit value to override. open_plot_device <- function(filename_base, width_px, height_px, pointsize = NULL) { if (is.null(pointsize)) pointsize <- scaled_pointsize(width_px, height_px) dims <- dpi_safe_dims(width_px, height_px) filename <- paste0(filename_base, ".", image_format) if (image_format == "png") { png(filename, width = dims[["width"]], height = dims[["height"]], res = plot_resolution, pointsize = pointsize) } else if (image_format == "jpg") { jpeg(filename, width = dims[["width"]], height = dims[["height"]], res = plot_resolution, pointsize = pointsize, quality = 95) } else if (image_format == "pdf") { pdf(filename, width = width_px / REF_DPI, height = height_px / REF_DPI, pointsize = pointsize) } else if (image_format == "svg") { svglite(filename, width = width_px / REF_DPI, height = height_px / REF_DPI, pointsize = pointsize) } else { stop("Unsupported image_format: ", image_format) } dims }
cap_mar_to_figure <- function(width_px, height_px, mar, dpi = plot_resolution, max_frac_vert = 0.7, max_frac_horz = 0.7, lpi = LINES_PER_INCH_REF) { h_in <- height_px / dpi w_in <- width_px / dpi vert_max <- h_in * lpi * max_frac_vert horz_max <- w_in * lpi * max_frac_horz mar <- as.numeric(mar) if (mar[1] + mar[3] > vert_max) { s <- vert_max / (mar[1] + mar[3] + 1e-6) mar[1] <- max(2, mar[1] * s) mar[3] <- max(2, mar[3] * s) } if (mar[2] + mar[4] > horz_max) { s <- horz_max / (mar[2] + mar[4] + 1e-6) mar[2] <- max(2, mar[2] * s) mar[4] <- max(1, mar[4] * s) } as.numeric(mar) }
## Close the plot device opened for the current plot. finish_plot <- function(png_dev) { dev.off(which = png_dev) }
## ── STEP 1: Load data ──────────────────────────────────────────────────────── counts <- read.delim(counts_file, check.names = FALSE, row.names = 1) ## Note: row.names = 1 is intentionally NOT used here, since the first ## column (sample IDs) is also needed further down as a regular data column ## (e.g. for the duplicate-sample check and when building the trait matrix). meta <- read.delim(metadata_file, check.names = FALSE)
## Sanity check: the samples in the counts matrix (columns) must match the ## samples listed in the first column of the metadata file. if (!setequal(colnames(counts), meta[[colnames(meta)[1]]])) { extra_counts <- setdiff(colnames(counts), meta[[1]]) extra_meta <- setdiff(meta[[1]], colnames(counts)) msg <- "Sample names in the counts matrix columns do not match the sample names in the first column of the metadata file." if (length(extra_counts) > 0) msg <- paste0(msg, " Samples in counts but not metadata: ", paste(head(extra_counts, 5), collapse = ", ")) if (length(extra_meta) > 0) msg <- paste0(msg, " Samples in metadata but not counts: ", paste(head(extra_meta, 5), collapse = ", ")) stop(msg) }
cat("Data loaded:", nrow(counts), "genes x", ncol(counts), "samples\n")
## ── STEP 2: Prepare expression matrix ─────────────────────────────────────── expr_data <- as.matrix(counts) mode(expr_data) <- "numeric"
if (log_transform) { expr_data <- log2(expr_data + 1) }
if (any(is.na(expr_data))) { expr_data <- expr_data[complete.cases(expr_data), , drop = FALSE] cat("Removed rows with missing values. New dimensions:", dim(expr_data), "\n") }
gene_variances <- apply(expr_data, 1, var, na.rm = TRUE) gene_variances[!is.finite(gene_variances)] <- NA_real_
filtered_expr_data <- expr_data variance_threshold <- NA_real_
if (filter_by_variance) { valid_var <- gene_variances[is.finite(gene_variances)] if (length(valid_var) == 0) { warning("No finite variances found; skipping variance filtering.") } else { variance_threshold <- quantile(valid_var, variance_quantile, na.rm = TRUE) filtered_expr_data <- expr_data[which(gene_variances > variance_threshold), , drop = FALSE] if (nrow(filtered_expr_data) == 0) { warning("Variance filter removed all genes; using unfiltered expression matrix.") filtered_expr_data <- expr_data } else { cat("Variance threshold (", variance_quantile * 100, "th percentile): ", variance_threshold, "\n", sep = "") } } } else { cat("Variance filtering disabled by user.\n") }
cat("Genes after variance filtering:", nrow(filtered_expr_data), "\n")
## Scale the height with the number of genes plotted, since the underlying ## histogram carries more information (finer bin detail) as gene counts grow; ## width stays fixed since a variance histogram doesn't need extra width. n_genes_for_plot01 <- nrow(filtered_expr_data) plot01_base_h <- max(700, round(500 + 150 * log10(max(n_genes_for_plot01, 10)))) plot01_dims <- open_plot_device("plots/01_gene_variance_distribution", 1000, plot01_base_h) png_dev <- dev.cur() ## Use R's literal default mar rather than querying par("mar") before a ## device is open (headless containers can mis-report the default). plot01_mar <- cap_mar_to_figure(plot01_dims[["width"]], plot01_dims[["height"]], c(5, 5, 5, 2) + 0.1) par(mar = plot01_mar, oma = c(0.5, 0.5, 0.8, 0.5)) var_plot <- gene_variances[is.finite(gene_variances) & gene_variances > 0] if (length(var_plot) > 1) { hist(log10(var_plot), breaks = 50, main = "Log10 Variance Distribution of Genes", xlab = "Log10(Variance)", col = "lightblue", border = "black") if (is.finite(variance_threshold) && variance_threshold > 0) { abline(v = log10(variance_threshold), col = "red", lwd = 2, lty = 2) } } else { plot.new() text(0.5, 0.5, "Insufficient variance values for histogram") } finish_plot(png_dev)
datExpr <- t(filtered_expr_data)
if (nrow(datExpr) < 2) stop("Too few samples after filtering.") if (ncol(datExpr) < 2) stop("Too few genes after filtering.")
sampleTree <- hclust(dist(datExpr), method = "average")
## Scale the clustering canvas with the number of samples so sample labels ## along the dendrogram stay readable instead of overlapping as cohorts grow. n_samples_for_plot02 <- nrow(datExpr) max_sample_label_chars <- max(nchar(rownames(datExpr)), na.rm = TRUE) sample_label_cex <- 0.7 ## Floors kept modest and growth capped: label length is handled entirely ## via plot02_mar_bottom below (the bottom margin), so it is intentionally ## NOT factored into the canvas size here -- doing so previously inflated ## the whole canvas (mostly empty space) just because sample IDs were long. plot02_base_w <- min(1600, max(700, 22 * n_samples_for_plot02 + 300)) plot02_base_h <- min(900, max(550, 10 * n_samples_for_plot02 + 350)) plot02_dims <- open_plot_device("plots/02_sample_clustering", plot02_base_w, plot02_base_h) png_dev <- dev.cur() ## Bottom margin must fit vertical sample IDs plus the subtitle below them. plot02_mar_bottom <- max(10, min(28, max_sample_label_chars * sample_label_cex * 0.42 + 6)) plot02_mar <- cap_mar_to_figure(plot02_dims[["width"]], plot02_dims[["height"]], c(plot02_mar_bottom, 6, 5, 2)) par(mar = plot02_mar, oma = c(0.4, 0.4, 0.8, 0.4), xpd = NA) plot(sampleTree, main = "Sample Clustering to Detect Outliers", xlab = "", ylab = "Height", cex = sample_label_cex, hang = 0.1) mtext("Height represents dissimilarity between samples", side = 1, line = max(plot02_mar[1] - 1.4, 3), cex = 0.75, col = "gray30") finish_plot(png_dev)
set.seed(123) sel_genes <- sample(seq_len(ncol(datExpr)), min(20, ncol(datExpr))) gene_axis_cex <- 1.05 ## Capped so a handful of very long gene IDs can't blow up the plot height. max_gene_label_chars <- min(40, max(nchar(colnames(datExpr)[sel_genes]), na.rm = TRUE)) ## Vertical tick labels (las = 2) consume roughly one text line per character. ## Use a slightly more conservative factor so labels still fit at high DPI. gene_label_lines <- max_gene_label_chars * gene_axis_cex * 0.45 expr_xlab_line <- ceiling(gene_label_lines) + 1 expr_box_bottom_mar <- expr_xlab_line + 2 plot03_base_w <- 1900 plot03_base_h <- max(800, 420 + max_gene_label_chars * 12) plot03_dims <- open_plot_device("plots/03_expression_data_distribution", plot03_base_w, plot03_base_h) png_dev <- dev.cur() ## Each mfrow panel is half the figure width; cap margins against that. plot03_panel_w <- as.integer(plot03_dims[["width"]] / 2) plot03_mar_hist <- cap_mar_to_figure(plot03_panel_w, plot03_dims[["height"]], c(6, 5, 5, 2)) plot03_mar_box <- cap_mar_to_figure(plot03_panel_w, plot03_dims[["height"]], c(expr_box_bottom_mar, 5, 5, 1.5)) par(mfrow = c(1, 2), mar = plot03_mar_hist, oma = c(0.4, 0.4, 0.6, 0.4)) hist(as.numeric(datExpr), breaks = 100, main = "Distribution of Expression Values", sub = ifelse(log_transform, "Log2-transformed counts", "Input counts"), xlab = "Expression Value", col = "lightblue", border = "white") par(mar = plot03_mar_box) boxplot(datExpr[, sel_genes, drop = FALSE], main = "Gene Expression Distributions\n(20 random genes)", xlab = "", ylab = "Expression Value", las = 2, cex.axis = gene_axis_cex, col = "lightblue", border = "gray40") mtext("Genes", side = 1, line = expr_xlab_line, cex = 0.9) par(mfrow = c(1, 1)) finish_plot(png_dev)
## ── STEP 3: Prepare trait data ─────────────────────────────────────────────── if (ncol(meta) < 2) { stop("Metadata must have sample names in the first column and at least one trait column.") }
sample_column <- colnames(meta)[1] if (anyDuplicated(meta[[sample_column]]) > 0) { stop("Duplicate sample names found in first column of metadata.") }
## ─── resolve trait column tokens (names or 1-based indices) ─── if (all(trait_tokens %in% colnames(meta))) { trait_columns <- trait_tokens } else { trait_indices <- suppressWarnings(as.integer(trait_tokens)) if (all(!is.na(trait_indices))) { if (any(trait_indices < 1 | trait_indices > ncol(meta))) { bad <- trait_indices[trait_indices < 1 | trait_indices > ncol(meta)] stop("Trait column index out of range: ", paste(bad, collapse = ", ")) } trait_columns <- colnames(meta)[trait_indices] } else { missing <- setdiff(trait_tokens, colnames(meta)) stop("Trait column(s) not found: ", paste(missing, collapse = ", ")) } }
meta_subset <- meta[, c(sample_column, trait_columns), drop = FALSE] trait_data <- prepare_trait_matrix(meta_subset, sample_col = 1)
sample_ids <- rownames(datExpr) missing_samples <- setdiff(sample_ids, rownames(trait_data)) if (length(missing_samples) > 0) { stop("Trait data missing sample(s): ", paste(missing_samples, collapse = ", ")) } trait_data <- trait_data[sample_ids, , drop = FALSE]
for (col in colnames(trait_data)) { trait_data[[col]] <- as.numeric(trait_data[[col]]) }
cat("Trait data prepared:", ncol(trait_data), "trait(s)\n") print(head(trait_data))
## ── STEP 4: Network construction ───────────────────────────────────────────── if (run_sample_gene_qc) { gsg <- goodSamplesGenes(datExpr, verbose = 3) if (!gsg[["allOK"]]) { datExpr <- datExpr[gsg[["goodSamples"]], gsg[["goodGenes"]], drop = FALSE] trait_data <- trait_data[rownames(datExpr), , drop = FALSE] } } else { cat("WGCNA goodSamplesGenes filtering disabled by user.\n") }
cat("After goodSamplesGenes:", ncol(datExpr), "genes,", nrow(datExpr), "samples\n") if (nrow(datExpr) < 2) { stop("Too few samples (", nrow(datExpr), ") remaining after goodSamplesGenes.") } if (ncol(datExpr) < min_module_size) { stop("Too few genes (", ncol(datExpr), ") for min_module_size=", min_module_size) }
set.seed(12345) net <- blockwiseModules( datExpr, power = soft_power, networkType = network_type, TOMType = tom_type, corType = cor_type, minModuleSize = min_module_size, reassignThreshold = 0, mergeCutHeight = merge_cut_height, numericLabels = TRUE, pamRespectsDendro = FALSE, saveTOMs = FALSE, nThreads = n_threads, verbose = 3 )
module_colors <- labels2colors(net[["colors"]]) names(module_colors) <- colnames(datExpr)
module_gene_counts <- table(module_colors) ## grey is the placeholder in WGCNA for unassigned genes so we exclude it when counting biologically meaningful modules ## any co-expression module can be assigned to grey, so it is excluded from the reported module count. cat("Modules identified (excluding grey):", sum(names(module_gene_counts) != "grey"), "\n") print(module_gene_counts)
## plotDendroAndColors manages its own margins internally; give it a ## DPI-scaled canvas and a modest outer margin so the title is not clipped. plot05_dims <- open_plot_device("plots/05_dendrogram_and_modules", 1600, 900) png_dev <- dev.cur() plot05_mar <- cap_mar_to_figure(plot05_dims[["width"]], plot05_dims[["height"]], c(3, 4, 4, 2)) par(mar = plot05_mar, oma = c(0.6, 0.6, 1.2, 0.6)) plotDendroAndColors( net[["dendrograms"]][[1]], module_colors[net[["blockGenes"]][[1]]], "Module Colors", dendroLabels = FALSE, hang = 0.03, addGuide = TRUE, guideHang = 0.05, main = "Gene Clustering Dendrogram and Module Colors", cex.colorLabels = 1.4, cex.main = 1.7, cex.axis = 1.3, cex.lab = 1.3 ) finish_plot(png_dev)
## ── STEP 5: Module eigengenes ──────────────────────────────────────────────── module_eigengenes <- orderMEs(net[["MEs"]])
## blockwiseModules() was run with numericLabels = TRUE, so net$MEs (and thus ## module_eigengenes) columns are named "ME0", "ME1", ... using raw numeric ## module labels instead of color names. Convert them to color-based names ## (e.g. "MEblue") here, once, so every downstream consumer of ## module_eigengenes (geneInfo.tsv's MM_ME* columns, the eigengene ## dendrogram, and the module-trait heatmap) shows labels consistent with ## the ModuleColor column instead of raw numbers. me_numeric_ids <- suppressWarnings(as.integer(sub("^ME", "", colnames(module_eigengenes)))) if (!anyNA(me_numeric_ids)) { colnames(module_eigengenes) <- paste0("ME", labels2colors(me_numeric_ids)) }
## Scale the eigengene dendrogram canvas with the number of modules and ## traits, matching the approach used for the module-trait heatmap (plot 07) ## below, so labels stay readable with many modules/traits; capped so very ## large module/trait counts don't blow up the canvas indefinitely. plot06_base_w <- min(3600, max(1900, 110 * ncol(trait_data) + 1100)) plot06_base_h <- min(3200, max(1400, 70 * ncol(module_eigengenes) + 800))
if (ncol(module_eigengenes) > 1) { ME_cor <- cor(module_eigengenes, use = "pairwise.complete.obs") ME_diss <- 1 - ME_cor ME_tree <- hclust(as.dist(ME_diss), method = "average") plot06_dims <- open_plot_device("plots/06_module_eigengene_dendrogram", plot06_base_w, plot06_base_h) png_dev <- dev.cur() plot06_mar <- cap_mar_to_figure(plot06_dims[["width"]], plot06_dims[["height"]], c(10, 6, 5, 2)) par(mar = plot06_mar, oma = c(0.4, 0.4, 0.8, 0.4), xpd = NA) plot(ME_tree, hang = 0.1, main = "Clustering of Module Eigengenes", xlab = "", sub = "", cex = 1.3, cex.main = 1.6, cex.axis = 1.3, cex.lab = 1.3) abline(h = merge_cut_height, col = "red", lty = 2) finish_plot(png_dev) } else { cat("Only one module found; skipping module eigengene dendrogram.\n") plot06_dims <- open_plot_device("plots/06_module_eigengene_dendrogram", plot06_base_w, plot06_base_h) png_dev <- dev.cur() plot06_mar <- cap_mar_to_figure(plot06_dims[["width"]], plot06_dims[["height"]], c(5, 5, 5, 2)) par(mar = plot06_mar, oma = c(0.4, 0.4, 0.8, 0.4)) plot.new() text(0.5, 0.5, "Only one module found;\ndendrogram not applicable", cex = 1.6) finish_plot(png_dev) }
## ── Genome-wide gene-module membership summary ───────────────────────────── ## For every gene (not just those in a trait-relevant module), correlate its ## expression profile with every module eigengene. This mirrors the classic ## WGCNA tutorial's gene_info summary table (Symbol, moduleColor, membership ## in every module + p-values), giving a single genome-wide reference table ## in addition to the per-trait/per-module tables produced later. gene_module_membership_all <- cor(datExpr, module_eigengenes, use = "pairwise.complete.obs") mm_pvalue_all <- corPvalueStudent(as.matrix(gene_module_membership_all), nrow(datExpr)) colnames(gene_module_membership_all) <- paste0("MM_", colnames(module_eigengenes)) colnames(mm_pvalue_all) <- paste0("p.MM_", colnames(module_eigengenes))
gene_info_all <- data.frame( Gene = colnames(datExpr), ModuleColor = module_colors[colnames(datExpr)], gene_module_membership_all, mm_pvalue_all, stringsAsFactors = FALSE ) gene_info_all <- gene_info_all[order(gene_info_all[["ModuleColor"]]), ]
write.table(gene_info_all, file = "results/geneInfo.tsv", sep = "\t", quote = FALSE, row.names = FALSE)
## ── STEP 6: Module-trait associations ──────────────────────────────────────── trait_data_aligned <- trait_data[rownames(module_eigengenes), , drop = FALSE] module_trait_cor <- cor(module_eigengenes, trait_data_aligned, use = "pairwise.complete.obs")
if (is.null(rownames(module_trait_cor))) rownames(module_trait_cor) <- colnames(module_eigengenes) if (is.null(colnames(module_trait_cor))) colnames(module_trait_cor) <- colnames(trait_data_aligned)
nSamples <- nrow(datExpr) module_trait_pval <- corPvalueStudent(module_trait_cor, nSamples)
text_matrix <- paste0(signif(module_trait_cor, 2), "\n(", signif(module_trait_pval, 1), ")") dim(text_matrix) <- dim(module_trait_cor)
## Scale the heatmap canvas with the number of traits/modules being plotted ## so that labels stay readable even with many traits or many modules; ## capped so cells don't balloon in size (and text along with them) when ## there are only a handful of traits/modules to display. The floors are ## kept modest so a small number of traits/modules doesn't produce a huge ## canvas with a handful of oversized, mostly-empty cells. trait_display_labels <- prettify_trait_label(colnames(trait_data_aligned)) n_traits_for_plot07 <- length(trait_display_labels) n_modules_for_plot07 <- ncol(module_eigengenes) plot07_base_w <- min(2200, max(650, 90 * n_traits_for_plot07 + 300)) plot07_base_h <- min(1900, max(500, 55 * n_modules_for_plot07 + 300)) plot07_dims <- open_plot_device("plots/07_module_trait_heatmap", plot07_base_w, plot07_base_h) png_dev <- dev.cur() plot07_mar <- cap_mar_to_figure(plot07_dims[["width"]], plot07_dims[["height"]], c(12, 12, 6, 4)) heatmap_cex_text <- max(1.1, min(1.6, 4.5 / sqrt(max(n_traits_for_plot07, n_modules_for_plot07)))) heatmap_cex_lab <- max(1.2, min(1.7, 5 / sqrt(max(n_traits_for_plot07, n_modules_for_plot07)))) par(mar = plot07_mar, oma = c(0.6, 0.6, 1, 0.6)) labeledHeatmap( Matrix = module_trait_cor, xLabels = trait_display_labels, yLabels = colnames(module_eigengenes), ySymbols = colnames(module_eigengenes), colorLabels = FALSE, colors = blueWhiteRed(50), textMatrix = text_matrix, setStdMargins = FALSE, cex.text = heatmap_cex_text, cex.lab.x = heatmap_cex_lab, cex.lab.y = heatmap_cex_lab, cex.main = 1.3, zlim = c(-1, 1), main = "Module-Trait Relationships\n(correlation and p-value)" ) finish_plot(png_dev)
## ── STEP 7 & 8: GS/MM and hub genes for each trait ───────────────────────── ## Gene significance, module membership, and hub-gene analysis are run ## independently for every trait column (numeric or one-hot encoded categorical). safe_label <- function(x) gsub("[^A-Za-z0-9._-]", "_", x)
common_samples <- Reduce(intersect, list( rownames(datExpr), rownames(trait_data_aligned), rownames(module_eigengenes) )) datExpr <- datExpr[common_samples, , drop = FALSE] trait_data_aligned <- trait_data_aligned[common_samples, , drop = FALSE] module_eigengenes <- module_eigengenes[common_samples, , drop = FALSE] nSamples <- nrow(datExpr)
module_trait_cor_sub <- cor(module_eigengenes, trait_data_aligned, use = "pairwise.complete.obs") if (is.null(rownames(module_trait_cor_sub))) rownames(module_trait_cor_sub) <- colnames(module_eigengenes) if (is.null(colnames(module_trait_cor_sub))) colnames(module_trait_cor_sub) <- colnames(trait_data_aligned)
for (trait_of_interest in colnames(trait_data_aligned)) { cat("\nAnalyzing trait:", trait_of_interest, "\n")
gene_significance <- cor(datExpr, trait_data_aligned[[trait_of_interest]], use = "pairwise.complete.obs") gene_significance_pval <- corPvalueStudent(as.numeric(gene_significance), nSamples) gene_significance <- as.numeric(gene_significance) names(gene_significance) <- colnames(datExpr) names(gene_significance_pval) <- colnames(datExpr)
## The most relevant module is the one whose eigengene shows the strongest ## absolute correlation with this trait (excluding unassigned grey module). candidate_modules <- setdiff(rownames(module_trait_cor_sub), c("MEgrey", "ME0")) if (length(candidate_modules) > 0) { trait_vec <- abs(module_trait_cor_sub[candidate_modules, trait_of_interest, drop = TRUE]) best_idx <- which.max(trait_vec) most_relevant_module <- candidate_modules[best_idx] } else { trait_vec <- abs(module_trait_cor_sub[, trait_of_interest, drop = TRUE]) best_idx <- which.max(trait_vec) most_relevant_module <- rownames(module_trait_cor_sub)[best_idx] } module_id_clean <- sub("^ME", "", most_relevant_module)
if (!is.na(suppressWarnings(as.numeric(module_id_clean)))) { module_name <- labels2colors(as.numeric(module_id_clean)) } else { module_name <- module_id_clean }
cat("Most relevant module:", most_relevant_module, "->", module_name, "\n")
module_genes <- names(module_colors)[module_colors == module_name] cat("Genes in module", module_name, ":", length(module_genes), "\n") if (length(module_genes) == 0) { warning("No genes found in module ", module_name, " for trait ", trait_of_interest, "; skipping.") next }
gene_module_membership <- cor( datExpr[, module_genes, drop = FALSE], module_eigengenes[, most_relevant_module, drop = TRUE], use = "pairwise.complete.obs" )
module_gene_info <- data.frame( Gene = module_genes, ModuleMembership = as.numeric(gene_module_membership), GeneSignificance = as.numeric(gene_significance[module_genes]), MM_pvalue = corPvalueStudent(as.numeric(gene_module_membership), nSamples), GS_pvalue = as.numeric(gene_significance_pval[module_genes]), stringsAsFactors = FALSE ) module_gene_info <- module_gene_info[order(-abs(module_gene_info[["ModuleMembership"]])), ]
trait_label <- safe_label(trait_of_interest)
plot08_dims <- open_plot_device( paste0("plots/08_gene_significance_vs_module_membership_", module_name, "_", trait_label), 1100, 800) png_dev <- dev.cur() plot08_mar <- cap_mar_to_figure(plot08_dims[["width"]], plot08_dims[["height"]], c(6, 7, 5, 2.5)) par(mar = plot08_mar, oma = c(0.5, 0.8, 0.8, 0.5)) plot(abs(module_gene_info[["ModuleMembership"]]), abs(module_gene_info[["GeneSignificance"]]), xlab = paste("Module Membership in", module_name, "module"), ylab = paste("Gene Significance for", trait_of_interest), main = paste("MM vs GS in", module_name, "module"), pch = 20, col = module_name, cex = 1) abline(lm(abs(GeneSignificance) ~ abs(ModuleMembership), data = module_gene_info), col = "red", lwd = 2) finish_plot(png_dev)
write.table(module_gene_info, file = paste0("results/module_gene_info_", module_name, "_", trait_label, ".tsv"), sep = "\t", quote = FALSE, row.names = FALSE)
adjacency_matrix <- adjacency(datExpr[, module_genes, drop = FALSE], power = soft_power, type = network_type, corFnc = cor_fnc) connectivity <- colSums(adjacency_matrix) - 1
hub_info <- data.frame( Gene = module_genes, ModuleMembership = as.numeric(gene_module_membership), GeneSignificance = as.numeric(gene_significance[module_genes]), Connectivity = as.numeric(connectivity), stringsAsFactors = FALSE ) hub_info <- hub_info[order(-hub_info[["Connectivity"]]), ]
write.table(hub_info, file = paste0("results/hub_genes_", module_name, "_", trait_label, ".tsv"), sep = "\t", quote = FALSE, row.names = FALSE)
is_top10 <- hub_info[["Connectivity"]] > quantile(hub_info[["Connectivity"]], 0.9, na.rm = TRUE)
plot09_dims <- open_plot_device( paste0("plots/09_hub_genes_", module_name, "_", trait_label), 1000, 750) png_dev <- dev.cur() plot09_mar <- cap_mar_to_figure(plot09_dims[["width"]], plot09_dims[["height"]], c(6, 7, 5, 3)) par(mar = plot09_mar, oma = c(0.5, 0.8, 0.8, 0.5)) plot(hub_info[["ModuleMembership"]], hub_info[["Connectivity"]], xlab = "Module Membership (MM)", ylab = "Connectivity (Intramodular)", main = paste("Hub Gene Identification in", module_name, "module"), pch = 20, col = ifelse(is_top10, "red", "black")) legend("topright", legend = c("Top 10% connected", "Other genes"), col = c("red", "black"), pch = 20, bty = "n") finish_plot(png_dev) }
## ── STEP 9: Co-expression network visualization ─────────────────────────────── gene_var <- apply(datExpr, 2, var, na.rm = TRUE) n_top <- min(1000, length(gene_var)) top_genes <- names(sort(gene_var, decreasing = TRUE))[1:n_top] cat("Calculating TOM for top", n_top, "variable genes...\n")
adj_subset <- adjacency(datExpr[, top_genes, drop = FALSE], power = soft_power, type = network_type, corFnc = cor_fnc) tom_subset <- TOMsimilarity(adj_subset, TOMType = tom_type) colnames(tom_subset) <- top_genes rownames(tom_subset) <- top_genes
tom_thresh <- quantile(tom_subset[upper.tri(tom_subset)], 0.95, na.rm = TRUE) adj_thresh <- tom_subset adj_thresh[adj_thresh < tom_thresh] <- 0 diag(adj_thresh) <- 0
network_graph <- graph_from_adjacency_matrix(adj_thresh, mode = "undirected", weighted = TRUE, diag = FALSE) gene_color_map <- setNames(module_colors, colnames(datExpr)) node_colors <- gene_color_map[top_genes] node_colors[is.na(node_colors)] <- "grey" ## Smaller nodes and more force-directed iterations reduce the visual ## overlap/clustering between densely-connected same-module genes. node_sizes <- log10(degree(network_graph) + 1) * 2 + 2
plot14_dims <- open_plot_device("plots/14_coexpression_network", 1800, 1800) png_dev <- dev.cur() plot14_mar <- cap_mar_to_figure(plot14_dims[["width"]], plot14_dims[["height"]], c(1.5, 1.5, 5, 1.5)) par(mar = plot14_mar, oma = c(0.4, 0.4, 1.2, 0.4)) set.seed(123) plot(network_graph, vertex.size = node_sizes, vertex.label = NA, vertex.color = node_colors, vertex.frame.color = NA, edge.width = 0.4, edge.color = "gray80", layout = layout_with_fr(network_graph, niter = 2000, start.temp = sqrt(vcount(network_graph)) * 2), main = paste0("Co-expression Network\n(Top ", n_top, " Variable Genes, Top 5% Connections)"), cex.main = 1.8) unique_colors <- unique(node_colors[node_colors != "grey"]) if (length(unique_colors) <= 10) { legend("topright", legend = unique_colors, col = unique_colors, pch = 19, cex = 1.1, title = "Modules", bty = "n") } finish_plot(png_dev)
## ── STEP 10: Module eigengene network ──────────────────────────────────────── me_correlation <- cor(module_eigengenes, use = "pairwise.complete.obs") me_pvalue <- corPvalueStudent(me_correlation, nSamples)
cor_thresh <- me_cor_threshold me_adj <- (abs(me_correlation) > cor_thresh) & (me_pvalue < 0.05) diag(me_adj) <- FALSE n_edges <- sum(me_adj) / 2 cat("\nNumber of module pairs with |correlation| >", cor_thresh, "and p < 0.05:", n_edges, "\n")
if (n_edges == 0) { fallback_thresh <- me_cor_threshold / 2 cat("\nNo edges at |r| >", cor_thresh, "; trying |r| >", fallback_thresh, "...\n") cor_thresh <- fallback_thresh me_adj <- (abs(me_correlation) > cor_thresh) & (me_pvalue < 0.05) diag(me_adj) <- FALSE n_edges <- sum(me_adj) / 2 cat("Edges at |r| >", cor_thresh, ":", n_edges, "\n") }
## module_eigengenes columns are already color-named (e.g. "MEblue") as of ## the conversion added in Step 5 above, so me_names here are color labels, ## not raw numeric ones — module_colors_me below is kept (rather than removed) ## for backward compatibility with any future numericLabels = TRUE usage, but ## now simply passes color names through unchanged in the normal case. me_names <- colnames(module_eigengenes) module_ids_me <- sub("^ME", "", me_names) module_colors_me <- module_ids_me numeric_me <- suppressWarnings(!is.na(as.numeric(module_ids_me))) module_colors_me[numeric_me] <- labels2colors(as.numeric(module_ids_me[numeric_me])) names(module_colors_me) <- me_names
plot15_base_dim <- 1300 if (sum(me_adj) > 0) { me_network <- graph_from_adjacency_matrix(me_adj, mode = "undirected", diag = FALSE) vertex_colors <- module_colors_me[vertex_attr(me_network, "name")] vertex_colors[is.na(vertex_colors)] <- "grey" vertex_attr(me_network, "color") <- vertex_colors
module_sizes_table <- table(module_colors) module_sizes_net <- module_sizes_table[vertex_colors] module_sizes_net[is.na(module_sizes_net)] <- 10 node_sizes_me <- log10(as.numeric(module_sizes_net) + 1) * 7 + 7
plot15_dims <- open_plot_device("plots/15_module_eigengene_network", plot15_base_dim, plot15_base_dim) png_dev <- dev.cur() plot15_mar <- cap_mar_to_figure(plot15_dims[["width"]], plot15_dims[["height"]], c(1.5, 1.5, 5, 1.5)) par(mar = plot15_mar, oma = c(0.4, 0.4, 1.2, 0.4)) set.seed(123) ## The module-eigengene network only ever has a handful of nodes (one ## per module), so a force-directed layout can bunch densely-correlated ## modules close together, making their labels overlap each other and ## the nodes. A circular layout guarantees even spacing between nodes ## regardless of how many edges exist; vertex.label.degree is set per ## node to the node's own angle around the circle, so each label is ## pushed straight outward away from the center (vertex.label.dist) ## instead of defaulting to the same direction for every node. me_circle_layout <- layout_in_circle(me_network) me_label_angles <- atan2(me_circle_layout[, 2], me_circle_layout[, 1]) plot(me_network, vertex.size = node_sizes_me, vertex.label = vertex_colors, vertex.label.cex = 1.3, vertex.label.color = "black", vertex.label.dist = 1.8, vertex.label.degree = me_label_angles, vertex.color = vertex_colors, vertex.frame.color = "black", edge.width = 2.5, edge.color = "gray40", layout = me_circle_layout, main = paste0("Module Eigengene Network\n(|correlation| > ", cor_thresh, ", p < 0.05)"), cex.main = 1.6) finish_plot(png_dev) } else { ## Always emit this plot (even as a placeholder) so downstream output ## discovery always finds the same, deterministic set of plot files. cat("No significant module-module edges after thresholding.\n") plot15_dims <- open_plot_device("plots/15_module_eigengene_network", plot15_base_dim, plot15_base_dim) png_dev <- dev.cur() plot15_mar <- cap_mar_to_figure(plot15_dims[["width"]], plot15_dims[["height"]], c(1, 1, 3, 1)) par(mar = plot15_mar) plot.new() text(0.5, 0.5, "No significant module-module\nedges found", cex = 1.2) finish_plot(png_dev) }
me_cor_labeled <- me_correlation rownames(me_cor_labeled) <- module_colors_me colnames(me_cor_labeled) <- module_colors_me
plot16_dims <- open_plot_device("plots/16_module_eigengene_correlation_heatmap", 1200, 1200) png_dev <- dev.cur() plot16_mar_multi <- cap_mar_to_figure(plot16_dims[["width"]], plot16_dims[["height"]], c(5, 4, 4, 2) + 0.1) plot16_mar_single <- cap_mar_to_figure(plot16_dims[["width"]], plot16_dims[["height"]], c(5, 5, 4, 2)) if (nrow(me_cor_labeled) > 1) { par(mar = plot16_mar_multi, cex.main = 1.3) heatmap(me_cor_labeled, col = colorRampPalette(c("blue", "white", "red"))(50), scale = "none", symm = TRUE, margins = c(8, 8), cexRow = 1.1, cexCol = 1.1, main = "Module Eigengene Correlation Heatmap") } else { par(mar = plot16_mar_single) image(x = 1, y = 1, z = matrix(me_cor_labeled[1, 1], nrow = 1), col = colorRampPalette(c("blue", "white", "red"))(50), zlim = c(-1, 1), axes = FALSE, main = "Module Eigengene Correlation Heatmap") axis(1, at = 1, labels = colnames(me_cor_labeled), las = 2, cex.axis = 1.2) axis(2, at = 1, labels = rownames(me_cor_labeled), las = 2, cex.axis = 1.2) } finish_plot(png_dev)
cat("\nWGCNA pipeline complete.\n") cat("Plots written to: plots/\n") cat("Results written to: results/\n")
